const body = $json.body && typeof $json.body === 'object' && !Array.isArray($json.body)
  ? $json.body
  : {};
const sessionId = typeof body.sessionId === 'string' ? body.sessionId : '';
const rawMessage = typeof body.message === 'string' ? body.message : '';
const message = rawMessage.trim();
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(sessionId)) {
  return {
    json: {
      valid: false,
      statusCode: 400,
      errorCode: 'INVALID_REQUEST',
      errorMessage: 'The conversation could not be identified. Reset it and try again.'
    }
  };
}

if (message.length === 0) {
  return {
    json: {
      valid: false,
      statusCode: 400,
      errorCode: 'INVALID_REQUEST',
      errorMessage: 'Enter a message and try again.'
    }
  };
}

if (message.length > 4000) {
  return {
    json: {
      valid: false,
      statusCode: 413,
      errorCode: 'MESSAGE_TOO_LONG',
      errorMessage: 'That message is too long. Keep it under 4,000 characters.'
    }
  };
}

return {
  json: {
    valid: true,
    sessionId,
    message
  }
};
